/* JAH demo program — JAH-QUAN-000001 */
/* Hydrogen Lyman-Alpha Jump photon demo */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("PHOTON DEMO — Hydrogen Lyman-Alpha Jump");
var lambda_nm=121.6;
var h=6.62607015e-34, c=299792458, eV=1.602176634e-19;
var E=h*c/(lambda_nm*1e-9);
console.log("wavelength: "+lambda_nm+" nm");
console.log("photon energy: "+E.toExponential(3)+" J = "+(E/eV).toFixed(4)+" eV");
console.log("frequency: "+(c/(lambda_nm*1e-9)).toExponential(3)+" Hz");

